from datetime import datetime, timezone

now_doc = apis.phone.get_current_date_and_time()
print('now_doc', now_doc)

def parse_date_str(s):
    fmts = [
        "%A, %B %d, %Y",
        "%A, %b %d, %Y",
        "%B %d, %Y",
        "%b %d, %Y",
        "%Y-%m-%d",
    ]
    for f in fmts:
        try:
            return datetime.strptime(s, f).date()
        except Exception:
            pass
    # fallback: try fromisoformat for YYYY-MM-DD
    try:
        return datetime.fromisoformat(s).date()
    except Exception:
        return None

now_date = parse_date_str(now_doc['date'])
print('parsed_now_date', now_date)
month_start = now_date.replace(day=1)
print('month_start', month_start)

# login token already in variable res from venmo.login earlier
venmo_access_token = res.get('access_token')

# fetch all pending received payment requests (paginated)
all_pending = []
page_index = 0
while True:
    page = apis.venmo.show_received_payment_requests(access_token=venmo_access_token, status='pending', page_index=page_index, page_limit=20)
    print('pending_page', page_index, 'count', len(page) if page else 0)
    if not page:
        break
    all_pending.extend(page)
    page_index += 1

print('pending_total', len(all_pending))

# parse created_at

def parse_dt(s):
    if not s:
        return None
    # normalize Z
    ss = s.replace('Z','+00:00')
    try:
        return datetime.fromisoformat(ss)
    except Exception:
        pass
    # try common formats
    fmts = ["%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"]
    for f in fmts:
        try:
            return datetime.strptime(s, f)
        except Exception:
            pass
    return None

candidates = []
for pr in all_pending:
    created = parse_dt(pr.get('created_at'))
    if not created:
        continue
    if created.date().year != month_start.year or created.date().month != month_start.month:
        continue
    sender_name = (pr.get('sender',{}).get('name') or '')
    sender_email = (pr.get('sender',{}).get('email') or '')
    if 'william' in sender_name.lower() or 'william' in sender_email.lower():
        candidates.append(pr)

print('candidates_count', len(candidates))
print('candidates_ids', [pr.get('payment_request_id') for pr in candidates])
print('candidates_details', [
    (pr.get('payment_request_id'), pr.get('sender',{}).get('name'), pr.get('sender',{}).get('email'), pr.get('amount'), pr.get('description'), pr.get('created_at'))
    for pr in candidates
])

